const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const ambient = new THREE.AmbientLight(0x7f8aa6, 0.35);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xfff5e6, 1.4);
keyLight.position.set(8, 12, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.bias = -0.0001;
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0xd6e6ff, 0.6);
fillLight.position.set(-8, 6, 4);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xaad6ff, 0.8, 25);
rimLight.position.set(0, 5, -8);
scene.add(rimLight);

const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(60, 60),
  new THREE.MeshStandardMaterial({ 
    color: 0xeef2f7, 
    roughness: 0.85, 
    metalness: 0.05 
  })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -3;
floor.receiveShadow = true;
scene.add(floor);

const gridHelper = new THREE.GridHelper(60, 60, 0xd0dae8, 0xe0e8f0);
gridHelper.position.y = -2.99;
scene.add(gridHelper);

const group = new THREE.Group();
scene.add(group);

const colorA = new THREE.Color(0xff4757);
const colorB = new THREE.Color(0x2ed573);

function createSource(color, xPos) {
  const sourceGroup = new THREE.Group();
  sourceGroup.position.set(xPos, 0, 0);

  const core = new THREE.Mesh(
    new THREE.SphereGeometry(0.25, 32, 32),
    new THREE.MeshPhysicalMaterial({
      color: color,
      emissive: color,
      emissiveIntensity: 2.5,
      metalness: 0.1,
      roughness: 0.2,
      clearcoat: 1.0,
      clearcoatRoughness: 0.1
    })
  );
  core.castShadow = true;
  sourceGroup.add(core);

  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(0.45, 32, 32),
    new THREE.MeshPhysicalMaterial({
      color: color,
      transparent: true,
      opacity: 0.15,
      transmission: 0.6,
      thickness: 0.5,
      roughness: 0,
      ior: 1.5,
      side: THREE.DoubleSide
    })
  );
  sourceGroup.add(glow);

  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(0.5, 0.6, 0.2, 32),
    new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.3,
      metalness: 0.6
    })
  );
  base.position.y = -0.3;
  base.receiveShadow = true;
  base.castShadow = true;
  sourceGroup.add(base);

  return { group: sourceGroup, core, glow };
}

const sourceA = createSource(colorA, -4);
const sourceB = createSource(colorB, 4);
group.add(sourceA.group);
group.add(sourceB.group);

const waveCount = 12;
const waveRingsA = [];
const waveRingsB = [];

function createWavePool(color, storage) {
  const geometry = new THREE.RingGeometry(0.2, 0.35, 64);
  const material = new THREE.MeshPhysicalMaterial({
    color: color,
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide,
    roughness: 0.2,
    metalness: 0.1,
    clearcoat: 0.8,
    emissive: color,
    emissiveIntensity: 0.5
  });

  for (let i = 0; i < waveCount; i++) {
    const mesh = new THREE.Mesh(geometry, material.clone());
    mesh.rotation.x = -Math.PI / 2;
    mesh.userData = { active: false, age: 0, speed: 3.5 + Math.random() * 0.5 };
    storage.push(mesh);
    group.add(mesh);
  }
}

createWavePool(colorA, waveRingsA);
createWavePool(colorB, waveRingsB);

const particleCount = 6000;
const geometry = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const colors = new Float32Array(particleCount * 3);
const sizes = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  const angle = Math.random() * Math.PI * 2;
  const radius = Math.random() * 12;
  positions[i * 3] = Math.cos(angle) * radius;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 0.5;
  positions[i * 3 + 2] = Math.sin(angle) * radius;
  sizes[i] = Math.random() * 0.08 + 0.02;
}

geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));

const particleMaterial = new THREE.PointsMaterial({
  size: 0.06,
  vertexColors: true,
  transparent: true,
  opacity: 0.9,
  sizeAttenuation: true,
  blending: THREE.AdditiveBlending
});

const particles = new THREE.Points(geometry, particleMaterial);
particles.position.y = 0.5;
group.add(particles);

function createLabel(text, color) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = 'rgba(255,255,255,0)';
  ctx.fillRect(0, 0, 512, 128);

  ctx.shadowColor = 'rgba(0,0,0,0.3)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 2;

  ctx.fillStyle = color;
  ctx.font = 'bold 48px Inter, system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 256, 64);

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const spriteMat = new THREE.SpriteMaterial({ 
    map: texture, 
    transparent: true,
    opacity: 0.9
  });
  const sprite = new THREE.Sprite(spriteMat);
  sprite.scale.set(4, 1, 1);
  return sprite;
}

const labelA = createLabel('Source A', '#ff4757');
labelA.position.set(-4, 1.8, 0);
group.add(labelA);

const labelB = createLabel('Source B', '#2ed573');
labelB.position.set(4, 1.8, 0);
group.add(labelB);

camera.position.set(0, 6, 14);
camera.lookAt(0, 0, 0);

let waveTimer = 0;

function updateWaves(waves, sourcePos, dt, time) {
  waves.forEach((wave, idx) => {
    if (wave.userData.active) {
      wave.userData.age += dt;
      const scale = 1 + wave.userData.age * wave.userData.speed;
      wave.scale.setScalar(scale);

      const life = wave.userData.age / 3.5;
      wave.material.opacity = Math.max(0, 0.6 * (1 - life) * Math.exp(-life * 2));
      wave.position.copy(sourcePos);
      wave.position.y = 0.05;

      if (wave.userData.age > 3.5) {
        wave.userData.active = false;
        wave.userData.age = 0;
        wave.scale.setScalar(1);
        wave.material.opacity = 0;
      }
    } else if (time % (3.5 / waveCount) < dt && Math.random() > 0.5) {
      if (!waves.some(w => w.userData.active && w.userData.age < 0.5)) {
        wave.userData.active = true;
        wave.userData.age = 0;
      }
    }
  });
}

function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();
  const t = clock.getElapsedTime();

  waveTimer += dt;

  sourceA.core.position.y = Math.sin(t * 4) * 0.15;
  sourceA.glow.position.y = sourceA.core.position.y;
  sourceA.glow.scale.setScalar(1 + Math.sin(t * 8) * 0.05);

  sourceB.core.position.y = Math.sin(t * 4 + Math.PI) * 0.15;
  sourceB.glow.position.y = sourceB.core.position.y;
  sourceB.glow.scale.setScalar(1 + Math.sin(t * 8) * 0.05);

  updateWaves(waveRingsA, sourceA.group.position, dt, t);
  updateWaves(waveRingsB, sourceB.group.position, dt, t);

  const pos = geometry.attributes.position.array;
  const col = geometry.attributes.color.array;

  const tempColor = new THREE.Color();
  const cA = colorA;
  const cB = colorB;

  for (let i = 0; i < particleCount; i++) {
    const x = pos[i * 3];
    const z = pos[i * 3 + 2];

    const d1 = Math.sqrt((x + 4) ** 2 + z ** 2);
    const d2 = Math.sqrt((x - 4) ** 2 + z ** 2);

    const wave1 = Math.sin(d1 * 2.5 - t * 8) * Math.exp(-d1 * 0.15);
    const wave2 = Math.sin(d2 * 2.5 - t * 8) * Math.exp(-d2 * 0.15);
    const interference = wave1 + wave2;

    pos[i * 3 + 1] = interference * 0.8 + 0.5;

    const intensity = (interference + 2) / 4;
    tempColor.copy(cA).lerp(cB, intensity);

    const brightness = 0.6 + intensity * 0.4;
    col[i * 3] = tempColor.r * brightness;
    col[i * 3 + 1] = tempColor.g * brightness;
    col[i * 3 + 2] = tempColor.b * brightness;
  }

  geometry.attributes.position.needsUpdate = true;
  geometry.attributes.color.needsUpdate = true;

  group.rotation.y = Math.sin(t * 0.15) * 0.1;

  rimLight.intensity = 0.6 + Math.sin(t * 1.5) * 0.15;

  renderer.render(scene, camera);
}

animate();

