const launchDuration = 10;
const maxAltitude = 40;
let launched = false;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  earth.rotation.y = t * 0.05;
  clouds.rotation.y = t * 0.07;

  if (t > 1 && !launched) {
    launched = true;
  }

  if (launched) {
    launchTime += 0.016;

    const progress = Math.min(launchTime / launchDuration, 1);
    const ease = progress * progress * (3 - 2 * progress);
    const altitude = ease * maxAltitude;

    spaceshipGroup.position.y = 0.5 + altitude;
    spaceshipGroup.position.z = -altitude * 0.3;
    spaceshipGroup.rotation.x = -ease * 0.2;

    glows.forEach((glow, i) => {
      const pulse = 0.7 + Math.sin(t * 20 + i) * 0.3;
      glow.material.opacity = pulse;
      const scale = 0.8 + pulse * 0.4;
      glow.scale.setScalar(scale);
    });

    const posArray = exhaustParticles.geometry.attributes.position.array;
    for (let i = 0; i < particleCount; i++) {
      lifetimes[i] += 0.016;

      if (lifetimes[i] > 0.5 || (i % 5 === 0 && Math.random() > 0.7)) {
        posArray[i * 3] = (Math.random() - 0.5) * 0.5;
        posArray[i * 3 + 1] = (Math.random() - 0.5) * 0.5;
        posArray[i * 3 + 2] = -2;
        lifetimes[i] = 0;
        velocities[i].x = (Math.random() - 0.5) * 0.2;
        velocities[i].y = (Math.random() - 0.5) * 0.2;
        velocities[i].z = -0.5 - Math.random() * 0.5;
      } else {
        posArray[i * 3] += velocities[i].x;
        posArray[i * 3 + 1] += velocities[i].y;
        posArray[i * 3 + 2] += velocities[i].z;
      }
    }
    exhaustParticles.geometry.attributes.position.needsUpdate = true;

    const camTargetY = 2 + altitude * 0.6;
    const camTargetZ = 8 + altitude * 0.8;
    camera.position.y += (camTargetY - camera.position.y) * 0.02;
    camera.position.z += (camTargetZ - camera.position.z) * 0.02;
    camera.lookAt(0, altitude * 0.5, 0);

    atmosphere.material.opacity = Math.max(0.05, 0.15 - altitude * 0.003);

  } else {
    spaceshipGroup.position.y = 0.5 + Math.sin(t * 2) * 0.02;
    glows.forEach((glow, i) => {
      glow.material.opacity = 0.3 + Math.sin(t * 5 + i) * 0.2;
    });
  }

  rimLight.intensity = 0.45 + Math.sin(t * 1.5) * 0.1;

  renderer.render(scene, camera);
}

