let time = 0;

function animate() {
    requestAnimationFrame(animate);
    time += 0.02;

    source1.position.y = Math.sin(time * 3) * 0.5;
    source2.position.y = Math.sin(time * 3 + Math.PI) * 0.5;

    wave1.scale.setScalar(1 + (time * 2) % 8);
    wave1.material.opacity = Math.max(0, 0.8 - ((time * 2) % 8) / 8);

    wave2.scale.setScalar(1 + ((time * 2 + 4) % 8));
    wave2.material.opacity = Math.max(0, 0.8 - (((time * 2 + 4) % 8) / 8));

    const pos = geometry.attributes.position.array;
    const col = geometry.attributes.color.array;

    for (let i = 0; i < particleCount; i++) {
        const x = pos[i * 3];
        const z = pos[i * 3 + 2];

        const d1 = Math.sqrt((x + 3) ** 2 + z ** 2);
        const d2 = Math.sqrt((x - 3) ** 2 + z ** 2);

        const amplitude1 = Math.sin(d1 * 2 - time * 6) * Math.exp(-d1 * 0.2);
        const amplitude2 = Math.sin(d2 * 2 - time * 6) * Math.exp(-d2 * 0.2);
        const combined = amplitude1 + amplitude2;

        pos[i * 3 + 1] = combined;

        const intensity = (combined + 2) / 4;
        col[i * 3] = intensity;
        col[i * 3 + 1] = 0.3;
        col[i * 3 + 2] = 1 - intensity;
    }

    geometry.attributes.position.needsUpdate = true;
    geometry.attributes.color.needsUpdate = true;

    group.rotation.y = Math.sin(time * 0.2) * 0.3;

    renderer.render(scene, camera);
}

